`,vb=`/* ── Atelier Console config engine ─────────────────────────────
   In the WordPress build every value maps 1:1 onto native options
   (get_option / Customizer / ACF) gated by edit_theme_options.
   Here it persists to localStorage to simulate the wp_options autosave.
   ─────────────────────────────────────────────────────────────── */
import { useSyncExternalStore } from "react";
import { IMG } from "./images";
import { localize, useI18n } from "./i18n";
import { contentT } from "./i18nContent";
import { contentT2 } from "./i18nContent2";
import { contentT3 } from "./i18nContent3";

/* Unified content lookup across all translation modules. */
function contentLookup(key: string, lang: "en" | "es" | "fr" | "de"): string | undefined {
  return contentT(key, lang) ?? contentT2(key, lang) ?? contentT3(key, lang);
}
export { contentLookup };

/* Lang + all UI strings live in i18n.ts (single source of truth).
   Re-exported here so existing consumers keep working. */
export type { Lang } from "./i18n";

/* ── design ── */
export interface DesignConfig {
  rose: string;
  roseDeep: string;
  gold: string;
  sage: string;
  accent: string;
  radius: number;
  baseFontSize: number;
  density: number;
  animSpeed: number;
  heroScrollSpeed: number;
  displayFont: "cormorant" | "fraunces" | "playfair";
  grain: boolean;
  motion: boolean;
  cursor: boolean;
  /* hero cinema palette */
  heroBase: string;
  heroInk: string;
  heroGold: string;
  heroChampagne: string;
}

/* ── concierge ── */
export interface ConciergeKnowledge {
  id: string;
  match: string; // regex
  en: string;
  es?: string;
  fr?: string;
  de?: string;
}
export interface ConciergeConfig {
  enabled: boolean;
  name: string;
  greeting: string;
  chime: boolean;
  openDelay: number;
  minDelay: number;
  accent: string;
  avatar: "gem" | "elena" | "sofia" | "amara" | "custom";
  avatarUrl: string;
  pos: "right" | "left";
  offsetY: number;
  knowledge: ConciergeKnowledge[];
}

/* ── slots (sections) ── */
export type BlockType = "info" | "cta" | "text-image" | "divider";
export interface CustomBlock {
  type: BlockType;
  title: string;
  text: string;
  buttonText: string;
  buttonTarget: string;
  image: string;
  align: "left" | "center";
  accent: string;
}
export interface SlotSettings {
  bg: string;
  spacing: "cozy" | "default" | "airy";
  animation: "fade" | "up" | "none";
  css: string;
}
export type Slot = { uid: string; enabled: boolean; settings: SlotSettings } & (
  | { kind: "builtin"; id: string }
  | { kind: "custom"; block: CustomBlock }
);
export interface LibraryItem {
  id: string;
  name: string;
  block: CustomBlock;
}

/* ── content ── */
export interface ContentStage {
  kicker: string;
  line1: string;
  line2: string;
  sub: string;
  image: string;
  alt: string;
  accent: string;
  overlay: number;
}
export interface ContentService {
  name: string;
  desc: string;
  dur: number;
  price: number;
}
export interface ContentServiceCat {
  label: string;
  note: string;
  items: ContentService[];
}
export interface ContentStylist {
  id: string;
  name: string;
  title: string;
  specialty: string;
  personality: string;
  quote: string;
  img: string;
}
export interface ContentTestimonial {
  quote: string;
  name: string;
  service: string;
  stars: number;
}
export interface ContentProduct {
  name: string;
  kind: string;
  desc: string;
  price: number;
  tags: string[];
  hue: [string, string];
}
export interface ContentPackage {
  name: string;
  tag: string;
  desc: string;
  dur: string;
  price: number;
  shape: string;
}
export interface ContentGalleryItem {
  id: number;
  title: string;
  kind: string;
  stylist: string;
  quote: string;
  image: string;
}
export interface ContentQuizQ {
  q: string;
  opts: { label: string; w: Record<string, number> }[];
}
export interface ContentConsultQ {
  id: string;
  label: string;
  sub: string;
  opts: string[];
}
export interface SectionHeading {
  title: string;
  italic: string;
  desc: string;
}

export interface Content {
  hero: { stages: ContentStage[]; cta: string; cta2: string };
  salon: { name: string; address: string; city: string; phone: string; email: string; tagline: string; img: string };
  footer: { word: string; sub: string; copyright: string; newsHeading: string; newsText: string };
  services: ContentServiceCat[];
  stylists: ContentStylist[];
  testimonials: ContentTestimonial[];
  products: ContentProduct[];
  packages: ContentPackage[];
  gallery: ContentGalleryItem[];
  amenities: { icon: string; title: string; desc: string }[];
  scents: string[];
  marquee: string[];
  stats: { end: number; suffix?: string; label: string }[];
  bookingAddons: { name: string; price: number }[];
  quiz: ContentQuizQ[];
  consult: ContentConsultQ[];
  headings: Record<string, SectionHeading>;
  /* admin-editable microcopy & list labels (defaults in DEFAULT_LABELS) */
  labels: Record<string, string>;
  tiers: string[];
  bookingSteps: string[];
  conciergeChips: string[];
  galleryFilters: { all: string; colour: string; cut: string; bridal: string; treatment: string };
}

/* ── virtual mirror (real recolor engine) ── */
export interface MirrorShade {
  id: string;
  label: string;
  h: number;
  s: number;
  l: number;
}
export interface MirrorModel {
  id: string;
  label: string;
  image: string;
  hair: string; // pre-sampled hair colour (hex)
}
export interface MirrorConfig {
  models: MirrorModel[];
  shades: MirrorShade[];
  tolerance: number;
  protectSkin: boolean;
  warmth: number;
  shine: number;
  camera: boolean;
}

export interface SiteConfig {
  design: DesignConfig;
  concierge: ConciergeConfig;
  slots: Slot[];
  library: LibraryItem[];
  content: Content;
  mirror: MirrorConfig;
  /* Auto-translation store: key → { es, fr, de }. Written by the
     translation engine whenever the admin saves content. Resolution
     order: admin label override → this map → built-in dictionaries →
     the English source string. */
  translations: Record<string, Partial<Record<"es" | "fr" | "de", string>>>;
  autoTranslate: boolean;
}

export interface Preset {
  name: string;
  builtIn?: boolean;
  design: DesignConfig;
}

