`,Eb=`/* ── On-device hair segmentation (MediaPipe ImageSegmenter) ──────
   Loads the multiclass selfie-segmentation model once in-browser.
   The model outputs per-pixel classes; we combine them into three
   probability maps the recolor engine trusts: hair, skin, clothes.
   Inference is fully local — the photo never leaves the device.
   If the model can't load (offline / unsupported), callers fall back
   to the classic heuristic engine. Nothing ever throws to the UI.
   ─────────────────────────────────────────────────────────────── */
/* Types are imported statically (erased at build); the heavy runtime is
   loaded on demand via dynamic import so it is code-split (8.6) and only
   fetched when the AI mirror is actually used. */
import type { ImageSegmenter, ImageSegmenterResult } from "@mediapipe/tasks-vision";

const WASM_CDN = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@1.0.1/wasm";
const MODEL_URL = "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_multiclass_256x256/float32/latest/selfie_multiclass_256x256.tflite";

/* Category indices for selfie_multiclass_256x256 */
const C = {
  background: 0,
  hair: 1,
  "body-skin": 2,
  "face-skin": 3,
  clothes: 4,
  "others(accessories)": 5,
};

export interface SegMasks {
  hair: Float32Array;
  skin: Float32Array;
  clothes: Float32Array;
  mw: number;
  mh: number;
}
export interface UpsampledSeg {
  hair: Float32Array;
  skin: Float32Array;
  clothes: Float32Array;
}

let segmenterPromise: Promise<ImageSegmenter | null> | null = null;

export function getSegmenter(): Promise<ImageSegmenter | null> {
  if (!segmenterPromise) {
    segmenterPromise = (async () => {
      /* Load the MediaPipe runtime on demand (code-split). */
      const { FilesetResolver, ImageSegmenter: Segmenter } = await import("@mediapipe/tasks-vision");
      const attempt = async (delegate: "GPU" | "CPU") => {
        const vision = await FilesetResolver.forVisionTasks(WASM_CDN);
        return Segmenter.createFromOptions(vision, {
          baseOptions: { modelAssetPath: MODEL_URL, delegate },
          runningMode: "IMAGE",
          outputCategoryMask: true,
          outputConfidenceMasks: true,
        });
      };
      try {
        return await attempt("GPU");
      } catch {
        try {
          return await attempt("CPU");
        } catch (e) {
          console.warn("[luxe-mirror] segmentation model unavailable — classic engine active.", e);
          segmenterPromise = null; // allow retry later
          return null;
        }
      }
    })();
  }
  return segmenterPromise;
}

function extractMasks(res: ImageSegmenterResult): SegMasks | null {
  const conf = res.confidenceMasks;
  if (!conf || conf.length === 0) return null;
  const mw = conf[0].width;
  const mh = conf[0].height;
  const n = mw * mh;
  const hair = new Float32Array(n);
  const skin = new Float32Array(n);
  const clothes = new Float32Array(n);
  const hairM = conf[C.hair]?.getAsFloat32Array();
  const faceSkinM = conf[C["face-skin"]]?.getAsFloat32Array();
  const bodySkinM = conf[C["body-skin"]]?.getAsFloat32Array();
  const clothesM = conf[C.clothes]?.getAsFloat32Array();
  for (let i = 0; i < n; i++) {
    hair[i] = hairM ? hairM[i] : 0;
    const fs = faceSkinM ? faceSkinM[i] : 0;
    const bs = bodySkinM ? bodySkinM[i] : 0;
    skin[i] = Math.max(fs, bs);
    clothes[i] = clothesM ? clothesM[i] : 0;
  }
  return { hair, skin, clothes, mw, mh };
}

export async function segmentHair(source: ImageBitmap | HTMLCanvasElement | HTMLImageElement): Promise<SegMasks | null> {
  const seg = await getSegmenter();
  if (!seg) return null;
  try {
    const res = seg.segment(source as HTMLImageElement);
    return extractMasks(res);
  } catch (e) {
    console.warn("[luxe-mirror] segmentation pass failed.", e);
    return null;
  }
}

/** Segment and map masks to the target image size.
    Bulletproof alignment: we hand the model a SQUARE canvas — the photo
    centred on a neutral grey field. Square-in means square-out under both
    letterbox and stretch conventions, so the mask maps back through one
    exact known transform: square mask → square composite → crop content. */
export async function segmentHairAt(
  source: HTMLCanvasElement | HTMLImageElement | ImageBitmap,
  w: number,
  h: number
): Promise<UpsampledSeg | null> {
  const S = Math.max(w, h);
  const sq = document.createElement("canvas");
  sq.width = S;
  sq.height = S;
  const c = sq.getContext("2d");
  if (!c) return null;
  c.fillStyle = "#808080";
  c.fillRect(0, 0, S, S);
  const offX = (S - w) / 2;
  const offY = (S - h) / 2;
  c.drawImage(source as CanvasImageSource, offX, offY);
  const m = await segmentHair(sq);
  if (!m) return null;

  const kx = m.mw / S;
  const ky = m.mh / S;
  const crop = (srcMask: Float32Array): Float32Array => {
    const out = new Float32Array(w * h);
    for (let y = 0; y < h; y++) {
      const sy = Math.min(m.mh - 1.001, Math.max(0, (offY + y) * ky));
      const y0 = sy | 0;
      const y1 = Math.min(m.mh - 1, y0 + 1);
      const fy = sy - y0;
      for (let x = 0; x < w; x++) {
        const sx = Math.min(m.mw - 1.001, Math.max(0, (offX + x) * kx));
        const x0 = sx | 0;
        const x1 = Math.min(m.mw - 1, x0 + 1);
        const fx = sx - x0;
        const v00 = srcMask[y0 * m.mw + x0];
        const v10 = srcMask[y0 * m.mw + x1];
        const v01 = srcMask[y1 * m.mw + x0];
        const v11 = srcMask[y1 * m.mw + x1];
        out[y * w + x] = (v00 * (1 - fx) + v10 * fx) * (1 - fy) + (v01 * (1 - fx) + v11 * fx) * fy;
      }
    }
    return out;
  };
  return { hair: crop(m.hair), skin: crop(m.skin), clothes: crop(m.clothes) };
}
