  const step = Math.max(2, Math.round(Math.max(width, height) / 140));
  const ring = (x: number, y: number) => {
    const i = (y * width + x) * 4;
    br += data[i]; bg2 += data[i + 1]; bb += data[i + 2]; bn++;
  };
  for (let x = 0; x < width; x += step) { ring(x, 0); ring(x, height - 1); }
  for (let y = 0; y < height; y += step) { ring(0, y); ring(width - 1, y); }
